  align-items: center;
  background: var(--bg-tertiary);
  border: 1px solid var(--glass-border);
  border-radius: 12px;
  padding: 18px 20px;
  gap: 20px;
}

.export-info h3 {
  font-size: 14px;
  font-weight: 700;
  margin: 0 0 4px;
}

.export-info p {
  font-size: 12px;
  color: var(--text-secondary);
  margin: 0;
}

.export-btns {
  display: flex;
  gap: 10px;
}

.unsloth-btn-export {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--glass-border);
  color: var(--text-primary);
  border-radius: 8px;
  padding: 8px 14px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.unsloth-btn-export:hover {
  background: rgba(255, 255, 255, 0.1);
}

.unsloth-btn-export.highlight {
  background: rgba(124, 106, 239, 0.2);
  border-color: var(--accent-color);
  color: var(--accent-light);
}

.unsloth-success-box {
  margin-top: 16px;
  background: rgba(16, 185, 129, 0.12);
  border: 1px solid rgba(16, 185, 129, 0.3);
  color: #10b981;
