}

.popular-badge {
  font-size: 10px;
  font-weight: 700;
  color: #f59e0b;
  background: rgba(245, 158, 11, 0.12);
  padding: 2px 6px;
  border-radius: 4px;
}

.active-badge {
  font-size: 11px;
  font-weight: 700;
  color: #10b981;
}

.model-desc-text {
  font-size: 12px;
