  color: var(--text-muted);
  font-size: 14px;
  cursor: pointer;
  padding: 4px;
  border-radius: 6px;
}

.unsloth-search-trigger:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.05);
}

.unsloth-primary-nav {
