  text-decoration: none;
  border-radius: 6px;
}

.unsloth-more-dropdown a:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}

/* ─── Recents Section ─── */
.unsloth-recents-section {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  padding: 8px 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.recents-header {
  padding: 4px 6px 8px;
}

.recents-title {
  font-size: 11px;
  font-weight: 600;
