  color: var(--text-dim);
}

.unsloth-settings-trigger {
  color: var(--text-muted);
  font-size: 15px;
  text-decoration: none;
  padding: 4px;
  border-radius: 6px;
}

.unsloth-settings-trigger:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.05);
}

/* ==========================================================================
   Unsloth Workspace & Main Area
   ========================================================================== */
.unsloth-app-workspace {
  display: flex;
  flex-direction: column;
  flex: 1;
  height: 100%;
  background: #0f1117;
  position: relative;
  overflow: hidden;
}

/* ─── Topbar ─── */
.unsloth-desktop-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 52px;
  padding: 0 24px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(15, 17, 23, 0.95);
  backdrop-filter: blur(12px);
  z-index: 20;
}

.unsloth-top-model-wrap {
  position: relative;
}

.unsloth-model-pill-btn {
  display: flex;
  align-items: center;
  gap: 9px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 8px;
  transition: background 0.15s ease;
}

.unsloth-model-pill-btn:hover {
  background: rgba(255, 255, 255, 0.05);
}

.unsloth-model-check {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  border: 1.5px solid #10b981;
  color: #10b981;
  font-size: 10px;
  font-weight: 800;
}

.unsloth-model-text-block {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.model-main-name {
  font-size: 15px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.2px;
}

.model-quant-sub {
  font-size: 12px;
  font-family: var(--font-mono);
  color: var(--text-dim, #7a7f8e);
}

.model-dropdown-chevron {
  font-size: 10px;
  color: var(--text-dim);
}

.unsloth-model-dropdown-menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  min-width: 320px;
  background: #161922;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.6);
  padding: 6px;
