}

.model-opt:hover {
  background: rgba(255, 255, 255, 0.05);
}

.model-opt.selected {
  background: rgba(124, 106, 239, 0.15);
}

.opt-name {
  font-size: 13px;
  font-weight: 600;
  color: #fff;
}

.opt-quant {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--accent-cyan);
}

/* Topbar Right Tools */
.unsloth-topbar-right {
  display: flex;
  align-items: center;
  gap: 14px;
}

.unsloth-token-gauge {
  display: flex;
  align-items: center;
  gap: 9px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
  padding: 4px 10px;
  border-radius: 9999px;
}

.token-nums {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-secondary);
}

.token-progress-track {
  width: 48px;
  height: 4px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 9999px;
  position: relative;
}

.token-progress-fill {
  height: 100%;
  background: #10b981;
  border-radius: 9999px;
  position: relative;
}

.token-dot {
  position: absolute;
  right: -2px;
  top: -2px;
  width: 8px;
  height: 8px;
  background: #10b981;
  border-radius: 50%;
  box-shadow: 0 0 6px #10b981;
}

.unsloth-top-icon-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 16px;
  padding: 6px;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.unsloth-top-icon-btn:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.05);
}

.unsloth-top-icon-btn.active {
  color: var(--accent-color);
  background: rgba(124, 106, 239, 0.15);
}

/* ─── Main Canvas Area ─── */
.unsloth-main-canvas-area {
  display: flex;
  flex-direction: column;
  flex: 1;
  height: calc(100% - 52px);
  position: relative;
  overflow: hidden;
}

.unsloth-chat-scroll-container {
  flex: 1;
  overflow-y: auto;
  padding: 24px 20px 160px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

