  align-items: center;
  justify-content: center;
}

.mascot-emoji {
  font-size: 38px;
}

.hero-greeting-title {
  font-size: 30px;
  font-weight: 700;
  color: #f1f3f7;
  letter-spacing: -0.6px;
  font-family: var(--font-sans);
  text-align: center;
  margin: 0;
}

/* ─── Messages Stream ─── */
.unsloth-messages-stream {
  width: 100%;
  max-width: 820px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ─── Floating Action Input Card ─── */
.unsloth-floating-input-wrapper {
  position: absolute;
  bottom: 24px;
  left: 0;
  right: 0;
  display: flex;
  justify-content: center;
  padding: 0 24px;
  pointer-events: none;
  z-index: 30;
}

.unsloth-input-card {
  width: 100%;
  max-width: 820px;
  background: #141720;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.6);
  padding: 14px 18px 12px;
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
  backdrop-filter: blur(20px);
}

.unsloth-textarea {
  width: 100%;
  background: transparent;
  border: none;
  outline: none;
  color: #f1f3f7;
  font-size: 15px;
  font-family: var(--font-sans);
  resize: none;
  max-height: 220px;
  line-height: 1.5;
}

.unsloth-textarea::placeholder {
  color: var(--text-dim, #5a5e6c);
}

.unsloth-card-bottom-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* Action Menu Button (+) */
.unsloth-action-menu-wrap {
  position: relative;
}

.unsloth-action-menu-btn {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #fff;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}

.unsloth-action-menu-btn:hover {
  background: rgba(255, 255, 255, 0.1);
}

.unsloth-action-menu-btn.open {
  background: rgba(255, 255, 255, 0.15);
  transform: rotate(90deg);
}

/* Action Popover Menu */
.unsloth-action-popover-menu {
  position: absolute;
  bottom: calc(100% + 12px);
  left: 0;
  min-width: 200px;
  background: #181b24;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 14px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.6);
  padding: 6px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  z-index: 100;
}

.popover-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  background: transparent;
  border: none;
  color: #d1d5db;
  font-size: 13px;
  border-radius: 8px;
  cursor: pointer;
  text-align: left;
  transition: all 0.15s ease;
}

.popover-item:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}

.popover-item .item-check {
