.unsloth-chip-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-muted);
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 9999px;
  padding: 4px 11px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.unsloth-chip-pill:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}

.unsloth-chip-pill.active {
  color: #10b981;
  border-color: rgba(16, 185, 129, 0.4);
  background: rgba(16, 185, 129, 0.1);
}

.unsloth-approve-wrap {
  position: relative;
}

.unsloth-approve-dropdown {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 0;
  min-width: 240px;
  background: #181b24;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 10px;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.5);
  padding: 4px;
  z-index: 100;
}

.approve-opt {
  padding: 8px 12px;
  font-size: 12px;
  color: #d1d5db;
  border-radius: 6px;
  cursor: pointer;
}

.approve-opt:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}

.approve-opt.active {
  color: #10b981;
  font-weight: 600;
}

/* Right Actions inside Card */
.card-right-actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 8px;
}

.unsloth-thinking-wrap {
  position: relative;
}

.unsloth-thinking-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: none;
  color: #10b981;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  padding: 4px 6px;
}

.unsloth-thinking-dropdown {
  position: absolute;
  bottom: calc(100% + 8px);
  right: 0;
  min-width: 170px;
  background: #181b24;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 10px;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.5);
  padding: 4px;
  z-index: 100;
}

.thinking-opt {
  padding: 7px 12px;
  font-size: 12px;
  color: #d1d5db;
  border-radius: 6px;
  cursor: pointer;
}

.thinking-opt:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}

.thinking-opt.active {
  color: #10b981;
  font-weight: 600;
}

.unsloth-mic-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 16px;
  cursor: pointer;
  padding: 4px;
  border-radius: 6px;
}

.unsloth-mic-btn:hover {
