/* Send Button: Signature Teal Circle (↑) */
.unsloth-send-btn {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: rgba(16, 185, 129, 0.2);
  color: rgba(255, 255, 255, 0.4);
  border: none;
  font-size: 17px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: not-allowed;
  transition: all 0.2s ease;
}

.unsloth-send-btn.active {
  background: #10b981;
  color: #000;
  cursor: pointer;
  box-shadow: 0 0 14px rgba(16, 185, 129, 0.4);
}

.unsloth-send-btn.active:hover {
  transform: scale(1.05);
}

.unsloth-send-btn.stop-btn {
  background: #ef4444;
  color: #fff;
  cursor: pointer;
}

/* ─── Right Drawer / Inspector ─── */
.unsloth-right-inspector {
  position: absolute;
  top: 52px;
  right: 0;
  bottom: 0;
  width: 46%;
  min-width: 380px;
  max-width: 680px;
  background: #12141c;
  border-left: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: -10px 0 30px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  z-index: 40;
  animation: slideLeft 0.2s ease-out;
}

@keyframes slideLeft {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

.inspector-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.inspector-tabs {
  display: flex;
  gap: 6px;
}

.insp-tab {
  background: transparent;
  border: none;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  padding: 6px 10px;
  border-radius: 6px;
  cursor: pointer;
}

.insp-tab.active {
  color: #fff;
  background: rgba(255, 255, 255, 0.06);
}

.insp-close-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 14px;
  cursor: pointer;
}

.inspector-body {
  flex: 1;
  overflow: hidden;
}

.inspector-editor-view {
  height: 100%;
