  align-items: center;
  gap: 5px;
  padding: 2px 6px;
  border-radius: 4px;
  transition: all 0.15s ease;
}

.crumb-title.editable:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
}

.crumb-edit-icon {
  font-size: 11px;
  opacity: 0.35;
  color: var(--text-muted);
  transition: opacity 0.15s ease;
}

.crumb-title.editable:hover .crumb-edit-icon {
  opacity: 1;
  color: var(--accent-color);
}

.crumb-title-input {
  background: #161b22;
  border: 1px solid var(--accent-color);
  border-radius: 4px;
  color: #f0f6fc;
  font-size: 13px;
  font-weight: 500;
  padding: 2px 8px;
  outline: none;
  min-width: 140px;
  max-width: 280px;
}

.agk-topbar-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.agk-topbar .topbar-tool-btn {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  border: none;
  background: transparent;
  color: #8b949e;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.agk-topbar .topbar-tool-btn:hover {
  background: #161b22;
  color: #f0f6fc;
}

.agk-topbar .topbar-tool-btn.active {
  background: rgba(124, 106, 239, 0.2);
  color: #9b8ef5;
}

.open-ide-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 12px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: #161b22;
  color: #c9d1d9;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.open-ide-btn:hover {
  background: #21262d;
  border-color: rgba(255, 255, 255, 0.2);
  color: #f0f6fc;
}

.open-ide-icon {
  font-size: 11px;
  color: #7c6aef;
}

/* ─── Canvas: feed + composer ─────────────────────────────────── */
.agk-canvas {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  background: transparent;
}

.agk-workspace.is-empty .agk-canvas {
  justify-content: center;
}

.agk-feed {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

.agk-feed-inner {
  max-width: 900px;
  margin: 0 auto;
  padding: 28px 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* User prompt — Codex-style outlined rounded bubble */
.agk-feed .message.user {
  justify-content: flex-end;
  width: 100%;
  max-width: 100%;
}

.agk-feed .message.user .avatar {
  display: none;
}

.agk-feed .message.user .bubble {
  width: fit-content;
  max-width: 80%;
  min-width: 32px;
  background: #1c2128;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 16px 16px 4px 16px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35);
  padding: 10px 18px;
  font-size: 14.5px;
  color: #f0f6fc;
  line-height: 1.55;
  word-break: keep-all;
  overflow-wrap: break-word;
  white-space: pre-wrap;
}

.user-message-text {
  display: inline-block;
  word-break: keep-all;
  overflow-wrap: break-word;
  white-space: pre-wrap;
}

/* Assistant prose — plain, no bubble chrome */
.agk-feed .message.assistant .avatar {
  background: transparent;
  box-shadow: none;
  width: 26px;
  height: 26px;
  font-size: 14px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.agk-feed .message.assistant .bubble {
  background: transparent;
  border: none;
  box-shadow: none;
  padding: 0;
  color: #e4e6eb;
  font-size: 14.5px;
  line-height: 1.7;
  word-break: break-word;
}

.agk-feed .message.assistant .bubble p {
  margin: 0 0 12px 0;
}

.agk-feed .message.assistant .bubble p:last-child {
  margin-bottom: 0;
}

.agk-feed .message.assistant .bubble ul,
.agk-feed .message.assistant .bubble ol {
  margin: 8px 0 14px 0;
  padding-left: 24px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.agk-feed .message.assistant .bubble li {
  margin: 0;
  padding: 0;
  line-height: 1.65;
  color: #d1d5db;
}

.agk-feed .message.assistant .bubble li::marker {
  color: var(--accent-color, #7c6aef);
}

.agk-feed .message.assistant .bubble h1,
.agk-feed .message.assistant .bubble h2,
.agk-feed .message.assistant .bubble h3,
.agk-feed .message.assistant .bubble h4 {
  color: #f3f4f6;
  font-weight: 600;
  line-height: 1.4;
}

.agk-feed .message.assistant .bubble h1:first-child,
.agk-feed .message.assistant .bubble h2:first-child,
.agk-feed .message.assistant .bubble h3:first-child,
.agk-feed .message.assistant .bubble h4:first-child {
  margin-top: 0;
}

.agk-feed .message.assistant .bubble h1 {
  font-size: 20px;
  margin: 24px 0 12px 0;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  color: #f0f6fc;
}

.agk-feed .message.assistant .bubble h2 {
  font-size: 17px;
  margin: 20px 0 10px 0;
  padding-bottom: 6px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  color: #f0f6fc;
}

.agk-feed .message.assistant .bubble h3 {
  font-size: 15px;
  margin: 16px 0 8px 0;
  color: #e6edf3;
}

.agk-feed .message.assistant .bubble h4 {
  font-size: 14px;
  margin: 14px 0 6px 0;
  color: #d0d7de;
}

.agk-feed .message.assistant .bubble hr {
  border: none;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  margin: 22px 0;
}

/* ─── Antigravity Assistant Identity Header ───────────────────────── */
.antigravity-assistant-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.assistant-identity-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-mono, monospace);
}

.assistant-spark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 6px;
  background: linear-gradient(135deg, rgba(124, 106, 239, 0.35), rgba(56, 189, 248, 0.3));
  border: 1px solid rgba(124, 106, 239, 0.5);
  color: #c4b5fd;
  font-size: 12px;
  box-shadow: 0 0 10px rgba(124, 106, 239, 0.3);
}

.assistant-identity-name {
  font-weight: 650;
  font-size: 13.5px;
  color: #f0f6fc;
  letter-spacing: -0.01em;
}

.assistant-identity-tag {
  font-size: 10px;
  padding: 1px 7px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #8b949e;
  font-weight: 500;
}

/* ─── Antigravity Thinking Process Box ────────────────────────────── */
.antigravity-thought-box {
  margin: 12px 0 16px 0;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  background: rgba(15, 20, 28, 0.55);
  backdrop-filter: blur(8px);
  overflow: hidden;
  transition: border-color 0.2s;
}

.antigravity-thought-box:hover {
  border-color: rgba(255, 255, 255, 0.15);
}

.antigravity-thought-box summary.thought-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  background: rgba(255, 255, 255, 0.025);
  cursor: pointer;
  user-select: none;
  font-size: 12px;
  color: #8b949e;
  font-family: var(--font-mono, monospace);
  list-style: none;
}

.antigravity-thought-box summary.thought-summary::-webkit-details-marker {
  display: none;
}

.thought-summary-left {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.thought-icon {
  font-size: 14px;
}

.thought-title {
  font-weight: 500;
  color: #c9d1d9;
}

.thought-status-badge {
  font-size: 10.5px;
  padding: 1px 8px;
  border-radius: 10px;
  background: rgba(56, 189, 248, 0.1);
  color: #38bdf8;
  border: 1px solid rgba(56, 189, 248, 0.22);
}

.thought-status-badge.streaming {
  background: rgba(251, 191, 36, 0.12);
  color: #fbbf24;
  border-color: rgba(251, 191, 36, 0.25);
}

.antigravity-thought-box .thought-body {
  padding: 12px 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  font-family: var(--font-mono, 'JetBrains Mono', monospace);
  font-size: 12px;
  line-height: 1.65;
  color: #8b949e;
  background: rgba(0, 0, 0, 0.15);
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 400px;
  overflow-y: auto;
}

/* ─── Antigravity Tool Cards ──────────────────────────────────────── */
.tool-timeline-badge.antigravity-tool-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  margin: 10px 0;
  padding: 8px 14px;
  border-radius: 8px;
  background: #161b22;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);
  font-family: var(--font-mono, monospace);
  font-size: 12px;
}

.tool-timeline-badge.antigravity-tool-card .tool-card-left {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #e6edf3;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-timeline-badge.antigravity-tool-card .tool-card-icon {
  font-size: 13px;
  color: #38bdf8;
}

.tool-timeline-badge.antigravity-tool-card .tool-card-title b {
  color: #f0f6fc;
  font-weight: 600;
}

.tool-timeline-badge.antigravity-tool-card .step-info {
  color: #8b949e;
  font-size: 11px;
  margin-left: 4px;
}

.tool-timeline-badge.antigravity-tool-card .tool-card-status {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 12px;
  background: rgba(16, 185, 129, 0.12);
  color: #10b981;
  border: 1px solid rgba(16, 185, 129, 0.28);
  font-weight: 500;
  flex-shrink: 0;
}

/* ─── Markdown Tables (Antigravity Style) ─────────────────────────── */
.agk-table-container {
  width: 100%;
  overflow-x: auto;
  margin: 16px 0;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  background: #161b22;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
}

.agk-markdown-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 13.5px;
  color: #d0d7de;
}

.agk-markdown-table th {
  background: rgba(255, 255, 255, 0.04);
  font-weight: 600;
  color: #f0f6fc;
  padding: 10px 14px;
  text-align: left;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  font-size: 13px;
}

.agk-markdown-table td {
  padding: 9px 14px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  line-height: 1.55;
}

.agk-markdown-table tr:last-child td {
  border-bottom: none;
}

.agk-markdown-table tr:nth-child(even) td {
  background: rgba(255, 255, 255, 0.015);
}

.agk-markdown-table tr:hover td {
  background: rgba(255, 255, 255, 0.035);
}

.agk-markdown-link {
  color: #58a6ff;
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: border-color 0.15s ease;
}

.agk-markdown-link:hover {
  border-bottom-color: #58a6ff;
}

/* ─── Message Action Buttons ───────────────────────────────────────── */
.message-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 14px;
  padding-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.msg-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.03);
  color: #8b949e;
  font-size: 12px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.msg-action-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #f0f6fc;
  border-color: rgba(255, 255, 255, 0.2);
}

.msg-action-btn.copied {
  background: rgba(16, 185, 129, 0.12);
  color: #10b981;
  border-color: rgba(16, 185, 129, 0.3);
}

/* Tip / Callout Block */
.tip-callout {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin: 14px 0 8px;
  padding: 12px 16px;
  border-radius: 10px;
  background: rgba(124, 106, 239, 0.08);
  border: 1px solid rgba(124, 106, 239, 0.22);
  color: #e2e8f0;
  font-size: 13.5px;
  line-height: 1.6;
}

.tip-callout-icon {
  font-size: 18px;
  flex-shrink: 0;
  line-height: 1.4;
}

.tip-callout-body {
  flex: 1;
}

.tip-callout-title {
  font-weight: 600;
  color: #c4b5fd;
  margin-right: 6px;
}

/* ─── Working indicator ───────────────────────────────────────── */
.agk-working-row {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: #8b949e;
  padding: 2px 0;
}

.working-label {
  font-weight: 500;
}

.working-elapsed {
  font-variant-numeric: tabular-nums;
  font-size: 11.5px;
  color: #6e7681;
}

.working-dots {
  display: inline-flex;
  gap: 3px;
}

.working-dots i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #8b949e;
  animation: agk-working-pulse 1.2s ease-in-out infinite;
}

.working-dots i:nth-child(2) { animation-delay: 0.15s; }
.working-dots i:nth-child(3) { animation-delay: 0.3s; }

@keyframes agk-working-pulse {
  0%, 70%, 100% { opacity: 0.25; transform: scale(0.85); }
  35% { opacity: 1; transform: scale(1); }
}

/* ─── Stream error banner (Antigravity error card) ────────────── */
.agk-error-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1px solid rgba(239, 68, 68, 0.3);
  border-radius: 14px;
  background: #1c1517;
  padding: 13px 16px;
  font-size: 13px;
  color: #fca5a5;
}

.error-banner-icon {
  color: #ef4444;
  font-size: 14px;
}

.error-banner-text {
  flex: 1;
  min-width: 0;
}

.error-banner-retry {
  border: 1px solid rgba(239, 68, 68, 0.3);
  background: #261b1e;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
  color: #fca5a5;
  padding: 5px 10px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.error-banner-retry:hover {
  background: #351c22;
}

/* ─── File edit summary card (Antigravity) ────────────────────── */
.agk-file-edit-card {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 16px;
  background: #14171f;
  overflow: hidden;
}

.file-edit-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 13px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.file-edit-icon {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: #1c2128;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: #c9d1d9;
}

.file-edit-title-wrap {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
}

.file-edit-title {
  font-size: 13.5px;
  font-weight: 600;
  color: #f0f6fc;
}

.file-edit-stats {
  display: inline-flex;
  gap: 6px;
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.stat-add { color: #10b981; }
.stat-del { color: #ef4444; }

.file-edit-actions {
  display: flex;
  gap: 6px;
}

.file-edit-btn {
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
  padding: 5px 11px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.file-edit-btn.ghost {
  border: none;
  background: transparent;
  color: #8b949e;
}

.file-edit-btn.ghost:hover {
  background: #1c2128;
  color: #f0f6fc;
}

.file-edit-btn.outline {
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: #161b22;
  color: #c9d1d9;
}

.file-edit-btn.outline:hover {
  background: #21262d;
  color: #f0f6fc;
}

.file-edit-rows {
  display: flex;
  flex-direction: column;
}

.file-edit-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 9px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.file-edit-path {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: #c9d1d9;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.file-edit-row-stats {
  display: inline-flex;
  gap: 6px;
  font-size: 11.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}

.file-edit-expand {
  width: 100%;
  border: none;
  background: transparent;
  color: #8b949e;
  font-size: 12px;
  font-weight: 500;
  padding: 9px 16px;
  cursor: pointer;
  text-align: left;
  transition: all 0.12s ease;
}

.file-edit-expand:hover {
  background: #161b22;
  color: #f0f6fc;
}

/* ─── Queued messages card (Codex) ────────────────────────────── */
.agk-queued-card {
  width: 100%;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  background: #14171f;
  overflow: hidden;
}

.queued-header {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 14px;
  border: none;
  background: transparent;
  cursor: pointer;
  text-align: left;
}

.queued-title {
  font-size: 13px;
  font-weight: 600;
  color: #f0f6fc;
}

.queued-count {
  min-width: 18px;
  height: 18px;
  border-radius: 6px;
  background: #21262d;
  color: #8b949e;
  font-size: 11px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
}

.queued-subtitle {
  flex: 1;
  font-size: 12px;
  color: #8b949e;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.queued-rows {
  display: flex;
  flex-direction: column;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.queued-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 14px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.queued-row:last-child {
  border-bottom: none;
}

.queued-text {
  flex: 1;
  min-width: 0;
  font-size: 13px;
  color: #c9d1d9;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.queued-drag-handle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #8b949e;
  cursor: grab;
  font-size: 11px;
  letter-spacing: -1px;
  user-select: none;
  padding: 0 4px 0 0;
  opacity: 0.6;
  transition: opacity 0.15s ease;
}

.queued-row:hover .queued-drag-handle {
  opacity: 1;
}

.queued-row.dragging {
  opacity: 0.4;
  background: #21262d;
}

.queued-row.drag-over {
  border-top: 2px solid #7c6aef;
}

.queued-actions {
  display: inline-flex;
  gap: 2px;
  opacity: 0;
  transition: opacity 0.15s ease;
}

.queued-row:hover .queued-actions {
  opacity: 1;
}

.queued-action-btn {
  width: 24px;
  height: 24px;
  border-radius: 6px;
  border: none;
  background: transparent;
  color: #8b949e;
  font-size: 12px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.12s ease;
}

.queued-action-btn:hover {
  background: #21262d;
  color: #f0f6fc;
}

.queued-action-btn.danger:hover {
  background: rgba(239, 68, 68, 0.15);
  color: #ef4444;
}

.queued-footer {
  display: flex;
  justify-content: flex-end;
  padding: 6px 12px 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.queued-clear-btn {
  background: transparent;
  border: none;
  font-size: 11px;
  color: #ef4444;
  cursor: pointer;
  padding: 3px 8px;
  border-radius: 4px;
  font-weight: 500;
  transition: all 0.15s ease;
}

.queued-clear-btn:hover {
  background: rgba(239, 68, 68, 0.15);
  color: #fca5a5;
}

/* ─── Composer zone ───────────────────────────────────────────── */
.agk-composer-zone {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.agk-composer-zone.docked {
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  padding: 0 24px 18px;
}

.agk-composer-zone.hero {
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  padding: 0 24px;
}

.agk-composer-card {
  width: 100%;
  display: flex;
  flex-direction: column;
}

.agk-input-main-card {
  width: 100%;
  background: #14171f;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 22px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.55);
  padding: 16px 18px 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* NX-09-F03: 첨부는 전송 전에 **보여야** 한다(보이지 않으면 붙였다는 사실을 믿을 수 없다). */
.agk-attachment-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.agk-attachment-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid rgba(229, 169, 59, 0.35);
  background: rgba(229, 169, 59, 0.12);
  color: var(--text-primary, #f0f6fc);
  font-size: 12px;
}

.agk-attachment-chip button {
  border: none;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
  padding: 0 2px;
}

.agk-input-main-card textarea,
.agk-input-main-card .codex-textarea {
  color: var(--text-primary, #f0f6fc) !important;
  caret-color: var(--accent-color, #e5a93b) !important;
}

.agk-input-main-card textarea::placeholder,
.agk-input-main-card .codex-textarea::placeholder {
  color: var(--text-muted, #8b949e) !important;
}

.agk-composer-zone.docked .codex-context-header-bar {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  background: #161b22;
  margin-bottom: 2px;
  align-self: flex-start;
}

/* Chip toolbar */
.agk-chip-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.agk-chip-group {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}

.tool-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 28px;
  padding: 0 10px;
  border-radius: 9999px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.03);
  color: #8b949e;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.tool-chip:hover {
  background: #21262d;
  color: #f0f6fc;
}

.tool-chip.active {
  background: rgba(16, 185, 129, 0.15);
  border-color: rgba(16, 185, 129, 0.35);
  color: #34d399;
}

.chip-icon {
  font-size: 12px;
}

.chip-chevron {
  font-size: 9px;
  color: #8b949e;
}

/* Access chip (amber = full access, green = read-only safe) */
.access-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 26px;
  padding: 0 10px;
  border-radius: 9999px;
  font-size: 11.5px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease;
}

.access-chip.amber {
  background: rgba(245, 158, 11, 0.15);
  border: 1px solid rgba(245, 158, 11, 0.35);
  color: #fbbf24;
}

.access-chip.amber:hover {
  background: rgba(245, 158, 11, 0.25);
}

.access-chip.safe {
  background: rgba(16, 185, 129, 0.15);
  border: 1px solid rgba(16, 185, 129, 0.35);
  color: #34d399;
}

.access-chip.safe:hover {
  background: rgba(16, 185, 129, 0.25);
}

/* MCP dropdown */
.agk-mcp-chip-wrap {
  position: relative;
}

.mcp-dropdown-menu {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 0;
  min-width: 240px;
  background: #161b22;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 10px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  padding: 4px;
  z-index: 100;
}

.mcp-opt {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 7px 10px;
  font-size: 12px;
  color: #c9d1d9;
  border-radius: 6px;
  border: none;
  background: transparent;
  cursor: pointer;
  text-align: left;
}

.mcp-opt:hover {
  background: #21262d;
  color: #f0f6fc;
}

.mcp-opt.selected {
  font-weight: 600;
  color: #f0f6fc;
}

.mcp-opt-status {
  font-size: 10.5px;
  font-weight: 600;
}

.mcp-opt-status.on {
  color: #34d399;
}

/* Hero composer variant: bigger breathing room */
.agk-composer-zone.hero .agk-input-main-card {
  border-radius: 26px;
  padding: 18px 20px 14px;
  box-shadow: 0 14px 44px rgba(0, 0, 0, 0.5);
}

.codex-suggested-prompt-line.hero-variant {
  align-self: center;
  max-width: 640px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ─── Unsloth hero (empty state) ──────────────────────────────── */
.unsloth-hero-head {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  text-align: center;
  margin-bottom: 22px;
}

.hero-mascot {
  font-size: 46px;
  line-height: 1;
  filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.3));
}

.hero-headline {
  margin: 0;
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #f0f6fc;
}

.hero-mark {
  background: rgba(124, 106, 239, 0.25);
  color: #c4b5fd;
  border-radius: 4px;
  padding: 0 6px;
}

.hero-subline {
  margin: 0;
  font-size: 13.5px;
  color: #8b949e;
  max-width: 460px;
  line-height: 1.6;
}

/* ─── Environment rail (Antigravity 우측 패널) ─────────────────── */
.agk-env-panel {
  width: 320px;
  flex: 0 0 320px;
  border-left: 1px solid rgba(255, 255, 255, 0.08);
  background: #0d1117;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

.env-tab-bar {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 10px 10px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.env-tab {
  border: none;
  background: transparent;
  font-size: 12.5px;
  font-weight: 600;
  color: #8b949e;
  padding: 7px 10px 9px;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  transition: color 0.15s ease, border-color 0.15s ease;
}

.env-tab:hover {
  color: #f0f6fc;
}

.env-tab.active {
  color: #f0f6fc;
  border-bottom-color: #7c6aef;
}

.env-tab-count {
  display: inline-flex;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 5px;
  background: rgba(124, 106, 239, 0.2);
  color: #a78bfa;
  font-size: 10px;
  font-weight: 700;
  align-items: center;
  justify-content: center;
  margin-left: 4px;
}

.env-tab-spacer {
  flex: 1;
}

.env-close-btn {
  border: none;
  background: transparent;
  color: #8b949e;
  font-size: 13px;
  cursor: pointer;
  padding: 4px 6px;
  border-radius: 6px;
}

.env-close-btn:hover {
  background: #21262d;
  color: #f0f6fc;
}

.env-scroll-area {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 12px 10px 20px;
}

.env-content-area {
  flex: 1;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.env-content-area > * {
  flex: 1;
  min-height: 0;
}

.env-section {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.env-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 8px;
}

.env-section-title {
  font-size: 12px;
  font-weight: 600;
  color: #8b949e;
}

.env-plus-btn {
  border: none;
  background: transparent;
  color: #8b949e;
  font-size: 13px;
  cursor: pointer;
  padding: 2px 5px;
  border-radius: 6px;
}

.env-plus-btn:hover {
  background: #21262d;
  color: #f0f6fc;
}

.env-row,
.env-row > .env-row-label {
  min-width: 0;
}

.env-row {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 9px;
  border: none;
  background: transparent;
  border-radius: 8px;
  padding: 8px 9px;
  font-size: 12.5px;
  color: #c9d1d9;
  cursor: pointer;
  text-align: left;
  transition: background 0.12s ease;
}

.env-row:hover {
  background: #161b22;
  color: #f0f6fc;
}

.env-row-icon {
  font-size: 13px;
  color: #8b949e;
  width: 16px;
  text-align: center;
  flex-shrink: 0;
}

.env-row-label {
  flex: 1;
  font-weight: 500;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.env-row-label.branch-name {
  font-family: var(--font-mono);
  font-size: 11.5px;
}

.env-row-stat {
  display: inline-flex;
  gap: 6px;
  font-size: 11.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}

.env-row-muted {
  color: #8b949e;
  font-weight: 400;
  font-size: 11.5px;
}

.env-chevron {
  font-size: 10px;
  color: #8b949e;
  transition: transform 0.18s ease;
  flex-shrink: 0;
}

.env-chevron.open {
  transform: rotate(180deg);
}

.env-row-group {
  display: flex;
  flex-direction: column;
}

.env-sub-list {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 2px 0 6px 12px;
}

.env-sub-empty {
  font-size: 11.5px;
  color: #8b949e;
  padding: 6px 10px;
}

.env-log-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 4px 10px;
  font-size: 11.5px;
  min-width: 0;
}

.env-log-hash {
  font-family: var(--font-mono);
  color: #7c6aef;
  flex-shrink: 0;
}

.env-log-msg {
  color: #8b949e;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.env-branch-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border: none;
  background: transparent;
  padding: 5px 10px;
  border-radius: 6px;
  font-size: 11.5px;
  color: #c9d1d9;
  cursor: pointer;
  text-align: left;
}

.env-branch-row:hover {
  background: #161b22;
  color: #f0f6fc;
}

.env-branch-row.current {
  font-weight: 600;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.12);
}

.env-branch-name {
  font-family: var(--font-mono);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.env-branch-current {
  font-size: 10px;
  color: #34d399;
  flex-shrink: 0;
}

.env-divider {
  height: 1px;
  background: rgba(255, 255, 255, 0.08);
  margin: 12px 6px;
}

.env-file-row {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border: none;
  background: transparent;
  padding: 6px 9px;
  border-radius: 7px;
  cursor: pointer;
  text-align: left;
}

.env-file-row:hover {
  background: #161b22;
}

.env-file-name {
  font-family: var(--font-mono);
  font-size: 11px;
  color: #c9d1d9;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.env-file-stat {
  display: inline-flex;
  gap: 5px;
  font-size: 10.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}

.env-file-status-letter {
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 700;
  color: #7c6aef;
  flex-shrink: 0;
}

.env-file-footer {
  font-size: 11px;
  color: #8b949e;
  padding: 7px 9px 0;
}

.env-mcp-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 9px;
  border-radius: 8px;
}

.env-mcp-row:hover {
  background: #161b22;
}

.env-mcp-icon {
  width: 22px;
  height: 22px;
  border-radius: 6px;
  background: rgba(124, 106, 239, 0.2);
  color: #a78bfa;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  flex-shrink: 0;
}

.env-mcp-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.env-mcp-name {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: #f0f6fc;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.env-mcp-status {
  font-size: 10.5px;
  color: #34d399;
}

.env-mcp-more {
  border: none;
  background: transparent;
  color: #8b949e;
  font-size: 11.5px;
  font-weight: 500;
  padding: 6px 9px;
  border-radius: 7px;
  cursor: pointer;
  text-align: left;
}

.env-mcp-more:hover {
  background: #21262d;
  color: #f0f6fc;
}

/* ═══════════════════════════════════════════════════════════════════
 * Agent Monitoring Panel — 환경 tab redesign
 * ═══════════════════════════════════════════════════════════════════ */

.agent-monitor-scroll {
  overflow-y: auto;
  padding: 8px;
  gap: 6px;
  display: flex;
  flex-direction: column;
}

/* ── ① Agent Status Card ──────────────────────────────────────── */
.agent-status-card {
  background: linear-gradient(135deg, rgba(124, 106, 239, 0.08) 0%, rgba(59, 130, 246, 0.06) 100%);
  border: 1px solid rgba(124, 106, 239, 0.15);
  border-radius: 10px;
  padding: 12px;
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}

.agent-status-card.running {
  border-color: rgba(52, 211, 153, 0.35);
  box-shadow: 0 0 12px rgba(52, 211, 153, 0.08);
}

.agent-status-card.idle {
  border-color: rgba(139, 148, 158, 0.2);
}

.agent-status-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
}

.agent-status-icon {
  font-size: 14px;
  line-height: 1;
}

.agent-status-card.running .agent-status-icon {
  color: #34d399;
  animation: agent-pulse 1.5s ease-in-out infinite;
}

.agent-status-card.idle .agent-status-icon {
  color: #8b949e;
}

@keyframes agent-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.agent-status-title {
  font-size: 12px;
  font-weight: 600;
  color: #f0f6fc;
  flex: 1;
}

.agent-status-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 10px;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.badge-running {
  background: rgba(52, 211, 153, 0.15);
  color: #34d399;
  border: 1px solid rgba(52, 211, 153, 0.3);
}

.badge-idle {
  background: rgba(139, 148, 158, 0.1);
  color: #8b949e;
  border: 1px solid rgba(139, 148, 158, 0.2);
}

.agent-active-tool {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  margin-bottom: 8px;
  background: rgba(52, 211, 153, 0.06);
  border-radius: 6px;
  border: 1px solid rgba(52, 211, 153, 0.12);
}

.active-tool-icon {
  color: #fbbf24;
  font-size: 11px;
}

.active-tool-name {
  font-family: var(--font-mono);
  font-size: 11px;
  color: #e5e7eb;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.active-tool-elapsed {
  font-size: 10px;
  color: #8b949e;
  font-family: var(--font-mono);
}

.agent-status-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 4px;
}

.status-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 4px 2px;
  background: rgba(255, 255, 255, 0.03);
  border-radius: 6px;
}

.status-stat .stat-value {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 700;
  color: #f0f6fc;
  line-height: 1.3;
}

.status-stat .stat-label {
  font-size: 9px;
  color: #8b949e;
  letter-spacing: 0.2px;
}

/* ── Section header (shared) ───────────────────────────────────── */
.agent-section {
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 10px;
  overflow: hidden;
}

.agent-section-header {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  border: none;
  background: transparent;
  cursor: pointer;
  width: 100%;
  text-align: left;
  transition: background 0.15s ease;
}

.agent-section-header:hover {
  background: rgba(255, 255, 255, 0.04);
}

.agent-section-header.static {
  cursor: default;
}

.agent-section-header.static:hover {
  background: transparent;
}

.agent-section-icon {
  font-size: 12px;
  flex-shrink: 0;
}

.agent-section-title {
  font-size: 11.5px;
  font-weight: 600;
  color: #f0f6fc;
  flex: 1;
}

.agent-section-count {
  font-size: 10px;
  font-weight: 600;
  color: #8b949e;
  background: rgba(255, 255, 255, 0.06);
  padding: 1px 6px;
  border-radius: 8px;
}

.agent-section-count.error-count {
  color: #f87171;
  background: rgba(248, 113, 113, 0.12);
}

/* ── ② Live Activity Feed ──────────────────────────────────────── */
.agent-activity-feed {
  max-height: 260px;
  overflow-y: auto;
  padding: 0 4px 4px;
}

.agent-activity-feed::-webkit-scrollbar {
  width: 4px;
}

.agent-activity-feed::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
}

.agent-activity-item {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 5px 6px;
  border-radius: 6px;
  transition: background 0.12s ease;
}

.agent-activity-item:hover {
  background: rgba(255, 255, 255, 0.04);
}

.activity-item-icon {
  font-size: 11px;
  width: 16px;
  text-align: center;
  flex-shrink: 0;
  margin-top: 1px;
}

.agent-activity-item.status-running .activity-item-icon {
  color: #34d399;
}

.agent-activity-item.status-done .activity-item-icon {
  color: #8b949e;
}

.agent-activity-item.status-failed .activity-item-icon {
  color: #f87171;
}

.activity-item-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.activity-item-label {
  font-size: 11px;
  font-weight: 500;
  color: #e5e7eb;
  line-height: 1.3;
}

.activity-item-detail {
  font-family: var(--font-mono);
  font-size: 10px;
  color: #6e7681;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.activity-item-meta {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.activity-running-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #34d399;
  animation: agent-pulse 1s ease-in-out infinite;
}

.activity-item-time {
  font-size: 10px;
  color: #6e7681;
  white-space: nowrap;
}

/* ── ③ Token Usage ─────────────────────────────────────────────── */
.token-usage-card {
  padding: 6px 10px 10px;
}

.token-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 3px 0;
}

.token-row.total {
  padding-top: 4px;
}

.token-label {
  font-size: 11px;
  color: #8b949e;
}

.token-value {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 600;
  color: #f0f6fc;
}

.token-value.prompt {
  color: #60a5fa;
}

.token-value.completion {
  color: #34d399;
}

.token-value.total {
  color: #e5a93b;
  font-size: 13px;
  font-weight: 700;
}

.token-divider {
  height: 1px;
  background: rgba(255, 255, 255, 0.08);
  margin: 3px 0;
}

.token-bar-container {
  display: flex;
  height: 4px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
  margin-top: 6px;
}

.token-bar-fill {
  height: 100%;
  transition: width 0.4s ease;
}

.token-bar-fill.prompt-fill {
  background: linear-gradient(90deg, #3b82f6 0%, #60a5fa 100%);
}

.token-bar-fill.completion-fill {
  background: linear-gradient(90deg, #059669 0%, #34d399 100%);
}

/* ── ④ File Changes ────────────────────────────────────────────── */
.agent-file-changes {
  padding: 0 4px 4px;
}

.agent-file-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border-radius: 5px;
  transition: background 0.12s ease;
}

.agent-file-item:hover {
  background: rgba(255, 255, 255, 0.04);
}

.file-item-icon {
  font-size: 10px;
  color: #fbbf24;
  flex-shrink: 0;
}

.file-item-name {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: #e5e7eb;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.file-item-time {
  font-size: 10px;
  color: #6e7681;
  white-space: nowrap;
  flex-shrink: 0;
}

/* ── ⑤ Error Log ───────────────────────────────────────────────── */
.agent-error-log {
  padding: 0 4px 4px;
}

.agent-error-item {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 5px 6px;
  border-radius: 5px;
  background: rgba(248, 113, 113, 0.04);
  border: 1px solid rgba(248, 113, 113, 0.1);
  margin-bottom: 3px;
}

.error-item-icon {
  color: #f87171;
  font-size: 11px;
  flex-shrink: 0;
  margin-top: 1px;
}

.error-item-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.error-item-msg {
  font-size: 10.5px;
  color: #fca5a5;
  word-break: break-word;
  line-height: 1.35;
}

.error-item-time {
  font-size: 9px;
  color: #6e7681;
}

/* ── Shared empty state ────────────────────────────────────────── */
.agent-empty {
  font-size: 11px;
  color: #6e7681;
  padding: 8px 10px;
  text-align: center;
}

.agent-empty.success {
  color: #34d399;
}

/* ── Code tab Git info ─────────────────────────────────────────── */
.code-tab-git {
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
}

/* Sidebar recent status dot (Codex blue dot) */
.recent-link {
  position: relative;
}

.recent-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #3b82f6;
  flex-shrink: 0;
  opacity: 0;
  transition: opacity 0.15s ease;
}

.recent-link:hover .recent-status-dot,
.recent-link.active .recent-status-dot {
  opacity: 1;
}

/* ─── Responsive: env rail overlays on narrow screens ─────────── */
@media (max-width: 1100px) {
  .agk-env-panel {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    z-index: 45;
    box-shadow: -12px 0 32px rgba(0, 0, 0, 0.1);
  }
}

@media (max-width: 720px) {
  .hero-headline {
    font-size: 24px;
  }

  .agk-composer-zone.docked,
  .agk-composer-zone.hero {
    padding: 0 14px 12px;
  }

  .agk-feed-inner {
    padding: 18px 14px 12px;
  }
}

/* ─── A11y contrast fixes (WCAG AA) ─────────── */
/* Dark sidebar/surfaces: #8b949e ≥4.5:1 on #0d0f0d / #0d1117 (was --text-muted #666e63 ~3.6:1).
   Light surfaces: #5d6470 ≥4.5:1 on white / #fbfbfc. */
.codex-section-label,
.usage-reset-note,
.folder-sub-preview,
.folder-sub-preview.muted,
.task-item,
.task-item.more,
.telemetrics-link,
.telemetrics-stat-label,
.terminal-slash,
.agent-empty {
  color: #8b949e;
}

/* Inline Sidebar colors (var(--text-muted) / var(--accent-color)) lose to author style
   unless overridden here. #9d8cff is 6.62:1 on #131613 (default accent #7c6aef is 4.48). */
.folder-task-list span,
.folder-task-list .task-item {
  color: #8b949e !important;
}

.folder-task-list button,
.voice-action-pill,
.voice-action-pill .sound-wave-icon,
.voice-action-pill .voice-text {
  color: #9d8cff !important;
}

.voice-action-pill:hover {
  color: #f0f6fc !important;
}

:root[data-theme="light"] {
  --text-muted: #5d6470;
}

:root[data-theme="light"] .folder-sub-preview,
:root[data-theme="light"] .folder-sub-preview.muted,
:root[data-theme="light"] .task-item,
:root[data-theme="light"] .telemetrics-link,
:root[data-theme="light"] .telemetrics-stat-label,
:root[data-theme="light"] .terminal-slash,
:root[data-theme="light"] .agent-empty,
.unsloth-desktop-sidebar.light-mode .folder-sub-preview,
.unsloth-desktop-sidebar.light-mode .folder-sub-preview.muted {
  color: #5d6470;
}

.avatar-initial-circle {
  background: #047857;
}

.env-section-title,
.env-row-muted,
.env-sub-empty,
.env-file-footer,
.queued-subtitle,
.working-elapsed {
  color: #8b949e;
}

.env-mcp-status,
.env-branch-current,
.tool-chip.active {
  color: #34d399;
}

.crumb-sep,
.env-chevron {
  color: #8b949e;
}

.recent-title {
  color: #c9d1d9;
}

/* ─── Activity timeline (Antigravity 활동 행) ─────────────────── */
.agk-activity {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  background: #161b22;
  overflow: hidden;
}

.activity-header {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 12px;
  border: none;
  background: transparent;
  cursor: pointer;
  text-align: left;
}

.activity-chips {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
}

.activity-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
  font-weight: 500;
  color: #8b949e;
  background: #21262d;
  border-radius: 9999px;
  padding: 3px 9px;
  white-space: nowrap;
}

.activity-count {
  flex: 1;
  text-align: right;
  font-size: 11.5px;
  color: #8b949e;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.activity-rows {
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  padding: 4px 0;
}

.activity-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 5px 14px;
  font-size: 12px;
  min-width: 0;
}

.activity-row-icon {
  width: 14px;
  text-align: center;
  color: #8b949e;
  flex-shrink: 0;
  align-self: center;
}

.activity-row-label {
  font-weight: 500;
  color: #f0f6fc;
  white-space: nowrap;
  flex-shrink: 0;
}

.activity-row-detail {
  flex: 1;
  min-width: 0;
  font-family: var(--font-mono);
  font-size: 11px;
  color: #8b949e;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.activity-row-time {
  font-size: 10.5px;
  color: #8b949e;
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}

.activity-row.status-running .activity-row-label::before {
  content: '';
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #f59e0b;
  margin-right: 6px;
  animation: agk-working-pulse 1.2s ease-in-out infinite;
}

.activity-row.status-done .activity-row-label::before {
  content: '';
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #10b981;
  margin-right: 6px;
}

.activity-row.status-failed .activity-row-label::before {
  content: '';
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ef4444;
  margin-right: 6px;
}

.usage-tokens-note {
  font-size: 10.5px;
  color: #5d6470;
  font-variant-numeric: tabular-nums;
}

.mcp-empty-row {
  cursor: default;
  color: #5d6470;
}

@media (max-width: 480px) {
  .task-execution-shell {
    padding: var(--space-2) !important;
  }
  .task-agent-row {
    padding: var(--space-1) var(--space-2) !important;
    gap: var(--space-1) !important;
  }
}

