/* ─── Real Project Management Section Styles ─────────────────────── */
.codex-section-label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 4px 6px 4px;
}

.project-add-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 4px;
  border: 1px solid rgba(0, 0, 0, 0.1);
  background: transparent;
  color: #6b7280;
  font-size: 15px;
  line-height: 1;
  cursor: pointer;
  transition: all 0.15s ease;
}

.project-add-btn:hover {
  background: rgba(0, 0, 0, 0.05);
  color: #111827;
  border-color: rgba(0, 0, 0, 0.25);
}

.project-remove-btn {
  margin-left: auto;
  background: transparent;
  border: none;
  color: #8b949e;
  font-size: 12px;
  padding: 2px 5px;
  border-radius: 4px;
  cursor: pointer;
  line-height: 1;
  opacity: 0.6;
  transition: opacity 0.15s ease, color 0.15s ease, background 0.15s ease;
}

.project-folder-box:hover .project-remove-btn {
  opacity: 1;
}

.project-remove-btn:hover {
  color: #ef4444 !important;
  background: rgba(239, 68, 68, 0.15) !important;
}

:root[data-theme="dark"] .project-add-btn,
html.dark .project-add-btn,
body.dark .project-add-btn {
  border-color: rgba(255, 255, 255, 0.15);
  color: #8b949e;
}

:root[data-theme="dark"] .project-add-btn:hover,
html.dark .project-add-btn:hover,
body.dark .project-add-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #f0f6fc;
  border-color: rgba(255, 255, 255, 0.3);
}

:root[data-theme="dark"] .project-remove-btn,
html.dark .project-remove-btn,
body.dark .project-remove-btn {
