}

.badge-disk {
  font-size: 10px;
  padding: 1px 4px;
  background: #f1f5f9;
  color: #334155;
  border-radius: 3px;
  font-weight: 500;
}

/* ─── QuantBadge (Phase 32 통합) — ChatPage 칩 + Model Hub 등급 공용 팔레트 ─── */
/* 베이스: 두 변형 공통. 크기/모양만 variant로 분기 */
.quant-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 700;
  font-family: var(--font-mono);
  flex-shrink: 0;
}
.quant-badge.chip {
  padding: 2px 6px 2px 3px;
  font-weight: 500;
  height: auto;
  width: auto;
  gap: 4px;
}
/* chip 안의 한 글자 등급 아이콘 — Model Hub grade 배지와 동일한 스타일 (Phase 39).
   ::before로 렌더해 칩의 textContent(토큰)를 유지 — getByText/클래스 단언 무회귀.
   data-grade는 QuantBadge가 주입. currentColor는 부모(칩)의 등급 색상을 상속받아
   테두리\xb7글자 색으로 사용한다 (color: inherit — 자체 color를 덮어쓰면 안 됨). */
.quant-badge.chip::before {
  content: attr(data-grade);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  border-radius: 3px;
  font-size: 9px;
  font-weight: 700;
  line-height: 1;
  flex-shrink: 0;
  color: inherit;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid currentColor;
}
.quant-badge.grade {
  width: 16px;
  height: 16px;
}

/* 등급 팔레트 (quantQuality util) — 라이트 */
.quant-badge.q-premium,
.badge-quant.q-premium, .quant-quality-badge.q-premium {
  background: rgba(22, 163, 74, 0.15);
  color: #15803d;
}
.quant-badge.q-high,
.badge-quant.q-high, .quant-quality-badge.q-high {
  background: rgba(2, 132, 199, 0.15);
  color: #0369a1;
}
.quant-badge.q-balanced,
.badge-quant.q-balanced, .quant-quality-badge.q-balanced {
  background: rgba(124, 58, 237, 0.15);
  color: #6d28d9;
}
.quant-badge.q-compact,
.badge-quant.q-compact, .quant-quality-badge.q-compact {
  background: rgba(234, 88, 12, 0.15);
  color: #c2410c;
}
.quant-badge.q-unknown,
.badge-quant.q-unknown, .quant-quality-badge.q-unknown {
  background: var(--bg-tertiary, #f1f5f9);
  color: var(--text-dim, #64748b);
}

/* 다크 테마 등급 팔레트 — 등급별 색상 유지 (flat gray 금지:
   색상 코딩이 배지의 존재 이유이므로 다크에서도 등급을 구분해야 한다).
   하우스 스타일: 배경 알파 0.2, 텍스트는 400-shade로 다크 가독성 확보. */
:root[data-theme="dark"] .quant-badge.q-premium,
:root[data-theme="dark"] .badge-quant.q-premium, :root[data-theme="dark"] .quant-quality-badge.q-premium {
  background: rgba(34, 197, 94, 0.2);
  color: #4ade80;
}
:root[data-theme="dark"] .quant-badge.q-high,
:root[data-theme="dark"] .badge-quant.q-high, :root[data-theme="dark"] .quant-quality-badge.q-high {
  background: rgba(14, 165, 233, 0.2);
  color: #38bdf8;
}
:root[data-theme="dark"] .quant-badge.q-balanced,
:root[data-theme="dark"] .badge-quant.q-balanced, :root[data-theme="dark"] .quant-quality-badge.q-balanced {
  background: rgba(139, 92, 246, 0.2);
  color: #a78bfa;
}
:root[data-theme="dark"] .quant-badge.q-compact,
:root[data-theme="dark"] .badge-quant.q-compact, :root[data-theme="dark"] .quant-quality-badge.q-compact {
  background: rgba(249, 115, 22, 0.2);
  color: #fb923c;
}
:root[data-theme="dark"] .quant-badge.q-unknown,
:root[data-theme="dark"] .badge-quant.q-unknown, :root[data-theme="dark"] .quant-quality-badge.q-unknown {
  background: rgba(148, 163, 184, 0.12);
  color: #94a3b8;
}

:root[data-theme="dark"] .model-group-title {
  color: #94a3b8;
}

:root[data-theme="dark"] .badge-provider.unsloth {
  background: rgba(194, 65, 12, 0.25);
  color: #fb923c;
}

:root[data-theme="dark"] .badge-provider.mlx {
  background: rgba(4, 120, 87, 0.25);
  color: #34d399;
}

:root[data-theme="dark"] .badge-disk {
  background: rgba(255, 255, 255, 0.08);
  color: #cbd5e1;
}

/* 다크 테마 등급 변형 — Model Hub 팔레트와 동일 */
/* ─── Session Disclosure Panel (세션 한도 고지 카드, Phase 9 복원) ─── */

.session-disclosure-panel {
  border: 1px solid var(--glass-border);
  border-radius: 10px;
  padding: 12px 14px;
  background: var(--bg-secondary);
  margin-bottom: 4px;
}

.session-disclosure-panel.level-healthy { border-color: rgba(22, 163, 74, 0.45); }
.session-disclosure-panel.level-warning { border-color: rgba(217, 119, 6, 0.55); background: rgba(217, 119, 6, 0.06); }
.session-disclosure-panel.level-exhausted { border-color: rgba(220, 38, 38, 0.55); background: rgba(220, 38, 38, 0.06); }

.disclosure-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
  font-size: 13px;
}

.level-healthy .disclosure-banner { color: #15803d; }
.level-warning .disclosure-banner { color: #b45309; }
.level-exhausted .disclosure-banner { color: #b91c1c; }

.disclosure-refresh {
  margin-left: auto;
  border: none;
  background: transparent;
  color: var(--text-dim);
  cursor: pointer;
  font-size: 13px;
  padding: 2px 6px;
  border-radius: 6px;
}

.disclosure-refresh:hover { background: var(--bg-tertiary); color: var(--text-primary); }

.disclosure-limits {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 10px;
}

.disclosure-limit-card {
  border: 1px solid var(--glass-border);
  border-radius: 8px;
  padding: 10px 12px;
}

.limit-card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
}

.limit-label { font-weight: 600; color: var(--text-primary); }
.limit-usage { font-family: var(--font-mono); color: var(--text-secondary); }

.limit-level-badge { margin-left: auto; font-size: 11px; }
.limit-level-badge.level-healthy { color: #15803d; }
.limit-level-badge.level-warning { color: #b45309; }
.limit-level-badge.level-exhausted { color: #b91c1c; }

.limit-gauge {
  height: 6px;
  border-radius: 9999px;
  background: var(--bg-tertiary);
  overflow: hidden;
  margin: 8px 0 6px;
}

.level-healthy .limit-gauge-fill { background: linear-gradient(90deg, #22c55e, #15803d); }
.level-warning .limit-gauge-fill { background: linear-gradient(90deg, #f59e0b, #b45309); }
.level-exhausted .limit-gauge-fill { background: linear-gradient(90deg, #ef4444, #b91c1c); }

.limit-message { margin: 0; font-size: 11px; color: var(--text-dim); }

.limit-countdown {
  font-family: var(--font-mono);
  font-weight: 600;
  color: #dc2626;
  background: rgba(220, 38, 38, 0.1);
  padding: 1px 5px;
  border-radius: 4px;
  display: inline-block;
}

:root[data-theme="dark"] .limit-countdown {
  color: #f87171;
  background: rgba(248, 113, 113, 0.12);
}

.disclosure-notices {
  margin: 10px 0 0;
  padding-left: 18px;
  font-size: 11px;
  color: var(--text-dim);
}

.disclosure-reset-date { margin: 8px 0 0; font-size: 11px; color: var(--text-dim); }
.disclosure-empty { margin: 8px 0 0; font-size: 12px; color: var(--text-dim); }
.disclosure-error-text { font-size: 12px; color: var(--text-dim); }

.disclosure-loading-spinner {
  display: inline-block;
  width: 14px;
  height: 14px;
  border: 2px solid var(--glass-border);
  border-top-color: var(--accent-color);
  border-radius: 50%;
  animation: disclosure-spin 0.8s linear infinite;
}

@keyframes disclosure-spin { to { transform: rotate(360deg); } }

:root[data-theme="dark"] .session-disclosure-panel.level-healthy { border-color: rgba(74, 222, 128, 0.35); }
:root[data-theme="dark"] .session-disclosure-panel.level-warning { border-color: rgba(251, 191, 36, 0.4); background: rgba(251, 191, 36, 0.08); }
:root[data-theme="dark"] .session-disclosure-panel.level-exhausted { border-color: rgba(248, 113, 113, 0.4); background: rgba(248, 113, 113, 0.08); }
:root[data-theme="dark"] .level-healthy .disclosure-banner { color: #4ade80; }
:root[data-theme="dark"] .level-warning .disclosure-banner { color: #fbbf24; }
:root[data-theme="dark"] .level-exhausted .disclosure-banner { color: #f87171; }

/* ─── Recipe preset selector (StudioPage STEP 4, Phase 24) ─── */

.recipe-preset-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  padding: 10px 12px;
  border: 1px solid var(--glass-border);
  border-radius: 8px;
  background: var(--bg-tertiary);
  margin-bottom: 14px;
}

.recipe-preset-row label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  white-space: nowrap;
}

.recipe-preset-values {
  font-size: 11px;
  color: var(--text-dim);
  font-family: var(--font-mono);
}

/* ─── Global disclosure banner (Phase 29 — shared store with settings card) ─── */

.session-disclosure-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  font-size: 13px;
  border-bottom: 1px solid transparent;
}
.session-disclosure-banner .banner-icon { font-size: 15px; }
.session-disclosure-banner .banner-text { flex: 1; min-width: 0; }
.session-disclosure-banner .banner-text strong { font-weight: 700; }
.session-disclosure-banner .banner-link {
  background: none;
  border: 1px solid currentColor;
  border-radius: 6px;
  color: inherit;
  cursor: pointer;
  font-size: 12px;
  padding: 3px 10px;
  white-space: nowrap;
}
.session-disclosure-banner .banner-link:hover { opacity: 0.85; }
.session-disclosure-banner .banner-dismiss {
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  font-size: 13px;
  opacity: 0.7;
  padding: 2px 6px;
}
.session-disclosure-banner .banner-dismiss:hover { opacity: 1; }

.session-disclosure-banner.level-warning {
  background: rgba(245, 158, 11, 0.12);
  border-bottom-color: rgba(245, 158, 11, 0.35);
  color: #b45309;
}
.session-disclosure-banner.level-exhausted {
  background: rgba(239, 68, 68, 0.12);
  border-bottom-color: rgba(239, 68, 68, 0.4);
  color: #b91c1c;
}

:root[data-theme="dark"] .session-disclosure-banner.level-warning {
  background: rgba(251, 191, 36, 0.1);
  border-bottom-color: rgba(251, 191, 36, 0.3);
  color: #fbbf24;
}
:root[data-theme="dark"] .session-disclosure-banner.level-exhausted {
  background: rgba(248, 113, 113, 0.1);
  border-bottom-color: rgba(248, 113, 113, 0.35);
  color: #f87171;
}
'
